import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"AI 绘画由哪些部分组成","description":"拆解 AI 绘画系统中的文本编码器、扩散模型、VAE、采样器、LoRA 与 ControlNet，理解各组件分工。","frontmatter":{"description":"拆解 AI 绘画系统中的文本编码器、扩散模型、VAE、采样器、LoRA 与 ControlNet，理解各组件分工。"},"headers":[],"relativePath":"concepts/components.md","filePath":"concepts/components.md","lastUpdated":1788308924000}'),o={name:"concepts/components.md"};function s(i,t,n,d,h,p){return e(),l("div",null,[...t[0]||(t[0]=[r(`<h1 id="ai-绘画由哪些部分组成" tabindex="-1">AI 绘画由哪些部分组成 <a class="header-anchor" href="#ai-绘画由哪些部分组成" aria-label="Permalink to &quot;AI 绘画由哪些部分组成&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 一次文生图由底模、文本编码器、VAE、采样器与调度器、提示词、生成参数和各类插件共同完成；每个部件只负责一段流程，动它只影响它负责的那一段。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/concepts/base-model">底模是什么</a>，知道底模在整个系统中的核心地位。</li><li>不要求用过 ComfyUI 或 WebUI；这份部件清单在主流工具里都成立，只是叫法和摆放位置不同。</li><li>先接受一个边界：本页讲“每个部件负责什么、动它会影响什么”，去噪的算法原理在下一篇 <a href="/concepts/how-it-works">基本原理</a> 展开。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>按顺序说出一幅文生图从提示词到成品经过哪些部件。</li><li>区分底模、文本编码器、VAE 这三个都叫“模型”的部件各管什么。</li><li>说明采样器、调度器、步数、CFG、seed 各自拧的是什么旋钮。</li><li>指出 LoRA 和 ControlNet 在流程中插入的位置。</li><li>用“固定 seed、单变量对照”的思路排查出图问题。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="一张图的完整流水线是什么样" tabindex="-1">一张图的完整流水线是什么样 <a class="header-anchor" href="#一张图的完整流水线是什么样" aria-label="Permalink to &quot;一张图的完整流水线是什么样&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>提示词（正向 / 负向）</span></span>
<span class="line"><span>   → 文本编码器：把文字变成模型能理解的向量</span></span>
<span class="line"><span>   → 初始噪声：一片随机噪声（seed 决定它长什么样）</span></span>
<span class="line"><span>   → 采样器 + 调度器：在底模上分多步去噪（LoRA 在此叠加，ControlNet 在此注入约束）</span></span>
<span class="line"><span>   → 潜空间图像（latent）</span></span>
<span class="line"><span>   → VAE 解码：latent → 人眼可见的图片</span></span></code></pre></div><p>记住顺序：文字先被读懂，噪声再被逐步清理，最后才翻译成图片。后面三个小节就按这个顺序展开。</p><p>每个部件的职责一句话：</p><ul><li><strong>底模（Checkpoint）</strong>：提供生成能力本身，决定风格、知识范围、分辨率习惯和生态兼容性。</li><li><strong>文本编码器（Text Encoder）</strong>：把提示词翻译成向量。常见有 CLIP（OpenAI 发布的图文对照文本编码器）、T5（Google 的另一代文本编码模型）等，不同代模型可能用不同编码器。</li><li><strong>VAE（Variational Autoencoder，变分自编码器）</strong>：在潜空间与像素图之间双向转换：编码进、解码出。</li><li><strong>采样器（Sampler）</strong>：决定每一步去噪怎么走。</li><li><strong>调度器（Scheduler）</strong>：决定噪声强度随步数怎么衰减，常与采样器成对出现。</li><li><strong>LoRA</strong>：挂在底模权重上的小型附加模型，补充角色、画风、服装等概念。</li><li><strong>ControlNet</strong>：注入线稿、深度、骨架等条件，约束构图和姿势。</li><li><strong>工作流（Workflow）</strong>：把以上部件按顺序连接的执行流程，在 ComfyUI 里表现为节点图。 <ul><li>常见形态：文生图、图生图、局部重绘、放大修复、参考图控制。</li><li>同一个模型可以配多种工作流；工作流只是流程，模型能力仍是基础。</li></ul></li></ul><h3 id="底模、文本编码器、vae-为什么常被弄混" tabindex="-1">底模、文本编码器、VAE 为什么常被弄混 <a class="header-anchor" href="#底模、文本编码器、vae-为什么常被弄混" aria-label="Permalink to &quot;底模、文本编码器、VAE 为什么常被弄混&quot;">​</a></h3><p>三个都是“模型文件”，但职责完全不重叠：</p><ul><li>底模负责“画”：它的权重就是生成能力。</li><li>文本编码器负责“读”：只处理文字，不碰像素。缺失或不匹配时，模型无法正确理解提示词，工作流可能直接报错。</li><li>VAE 负责“翻译”：只做潜空间与像素图的转换，不参与理解语言，也不能单独生成图。VAE 不合适时，常见症状是颜色发灰、对比度异常、细节不自然。</li><li>三者的体积量级也不同：底模最大，文本编码器次之，VAE 较小；新一代模型常把三者拆成多个文件发布，缺哪样、症状各不相同——缺文本编码器读不懂提示词，缺 VAE 颜色异常，缺底模则什么都出不来。</li></ul><p>分开记的办法：文字进来走编码器，画的过程靠底模和插件，出图时走 VAE。下次遇到“加载失败”或“效果不对”，先问一句：少的是哪个部件？</p><h3 id="采样器、步数、cfg、seed-这四个旋钮各拧什么" tabindex="-1">采样器、步数、CFG、seed 这四个旋钮各拧什么 <a class="header-anchor" href="#采样器、步数、cfg、seed-这四个旋钮各拧什么" aria-label="Permalink to &quot;采样器、步数、CFG、seed 这四个旋钮各拧什么&quot;">​</a></h3><ul><li><strong>采样器与调度器</strong>：换它们等于换“走法”——同一路程走出来的细节、稳定性和随机感可能不同，没有绝对好坏，常用组合见教程或模型页推荐。</li><li><strong>步数（Steps）</strong>：去噪迭代次数。太少画面粗糙、不完整；适中后质量趋于稳定；再多通常只是更慢。不同模型推荐步数不同，Turbo 类模型专门为此减少步数。</li><li><strong>CFG（Classifier-Free Guidance，无分类器引导）</strong>：模型听提示词的程度。太低自由发挥、容易跑题；太高可能颜色过饱和、结构变差。不同模型敏感度不同，按模型卡推荐值起步。</li><li><strong>seed（随机种子）</strong>：决定起点的那片初始噪声。固定 seed 才能复现结果、做对照实验。</li></ul><p>新手不必逐个穷举组合：先用教程或模型页推荐的一整套参数，再按需要逐个动。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新手起步路径：</span></span>
<span class="line"><span>教程推荐的模型 + 推荐参数 → 固定 seed 出基准图 → 一次只动一个旋钮 → 记录结论</span></span></code></pre></div><p>每次只动一格，一格一格建立你对这套工具的手感。</p><h3 id="lora-和-controlnet-插在哪一段" tabindex="-1">LoRA 和 ControlNet 插在哪一段 <a class="header-anchor" href="#lora-和-controlnet-插在哪一段" aria-label="Permalink to &quot;LoRA 和 ControlNet 插在哪一段&quot;">​</a></h3><ul><li><strong>LoRA</strong> 挂在底模的权重上，作用于整个去噪过程，改变“画面往哪个方向生成”。它需要匹配底模生态，不是所有模型都能通用。</li><li><strong>ControlNet</strong> 把一张条件图（线稿、深度图、骨架图等）与提示词一起喂给去噪过程，管“构图和姿势”，不改画风。</li><li><strong>提示词</strong> 在最上游的文本编码阶段起作用。通常分两部分：<strong>正向提示词</strong>写希望出现的内容，<strong>负向提示词</strong>写希望减少或避免的内容。它更像引导而不是命令，模型不一定完全服从。</li></ul><p>三者都在“画”的阶段生效，但对象不同：提示词管语义引导，LoRA 管内容倾向，ControlNet 管空间结构。</p><h2 id="最小推演-只改一个变量的对照实验" tabindex="-1">最小推演：只改一个变量的对照实验 <a class="header-anchor" href="#最小推演-只改一个变量的对照实验" aria-label="Permalink to &quot;最小推演：只改一个变量的对照实验&quot;">​</a></h2><p>想验证某个旋钮有没有用，最可靠的办法是：固定其他一切，只改它。假设固定同一句提示词、同一个底模、同一个 seed：</p><table tabindex="0"><thead><tr><th>对照组</th><th>固定不变</th><th>唯一变量</th><th>观察点</th><th>预期</th></tr></thead><tbody><tr><td>A1 vs A2</td><td>提示词、seed、模型、CFG、采样器</td><td>步数 10 → 30</td><td>线条与细节完成度</td><td>30 步明显更完整</td></tr><tr><td>B1 vs B2</td><td>提示词、seed、模型、步数、采样器</td><td>CFG 低 → 高</td><td>跟词程度与画面自然度</td><td>更跟词，但过高可能僵硬</td></tr><tr><td>C1 vs C2</td><td>全部参数</td><td>LoRA 开 / 关</td><td>目标概念是否出现</td><td>开启后概念出现</td></tr></tbody></table><p>推演步骤：</p><ol><li>第一步永远固定 seed：起点相同，差异才能归因到那个变量。</li><li>每轮只改一个旋钮，其余全部保持原样。</li><li>记录差异：A 组的差异归给步数，B 组归给 CFG，C 组归给 LoRA。</li><li>一次实验只回答一个问题；要比较两个变量，就做两轮实验。</li><li>结论只对“这套固定条件”成立：换了模型或分辨率，可能要重新验证。</li></ol><p>这个推演只说明“单变量对照”的实验思路，不等于每次改动都有精确可复现的效果——生成过程仍含随机性，模型换代也会让结论过期，但这正是先固定 seed 的原因。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>把常见部件当成“旋钮”来理解，下表给出各自的典型影响和新手建议。先对这套“旋钮面板”有整体印象，再逐个上手：</p><table tabindex="0"><thead><tr><th>部件 / 参数</th><th>默认作用</th><th>调大 / 调小的典型效果</th><th>新手建议</th></tr></thead><tbody><tr><td>步数</td><td>去噪迭代次数</td><td>多：更完整、更慢；少：快但粗糙</td><td>用模型卡或教程推荐值起步</td></tr><tr><td>CFG</td><td>听提示词的强度</td><td>高：更跟词但易过饱和；低：自由但跑题</td><td>从推荐值试起，小步调整</td></tr><tr><td>采样器</td><td>每步去噪怎么走</td><td>换用改变细节与稳定感，无大小之分</td><td>用教程推荐的成对组合</td></tr><tr><td>调度器</td><td>噪声强度随步数衰减</td><td>与采样器配合影响收敛节奏</td><td>同上，不单独折腾</td></tr><tr><td>LoRA 强度</td><td>附加概念的影响量</td><td>高：概念过强画面崩；低：几乎无感</td><td>从低权重（如 0.3 到 0.5）试起再上调</td></tr><tr><td>seed</td><td>初始噪声来源</td><td>固定：可复现；随机：探索新图</td><td>排查问题时固定</td></tr></tbody></table><p>表里没有底模：它不是旋钮，是地基——只能换，不能调；换底模的影响远大于任何旋钮。调旋钮的前提，永远是底模本身具备对应能力。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“VAE 也能生成图片”</strong>：VAE 只做潜空间与像素图的相互转换，单独一个 VAE 生成不了任何图。</li><li><strong>“LoRA 可以当底模用”</strong>：LoRA 是对特定底模权重的增量修改，必须挂在匹配的底模上才有效。</li><li><strong>“参数调好能弥补模型的不足”</strong>：底模没学过的概念，插件和旋钮都补不上（详见<a href="/concepts/base-model">底模是什么</a>）；旋钮只影响“已有能力怎么发挥”。</li><li><strong>“文本编码器不用管”</strong>：不同代模型可能用 CLIP、T5 等不同编码器，缺失或不匹配会直接报错或完全不理解提示词。</li><li><strong>“一次改多个参数更快出结果”</strong>：多变量一起改就无法归因；先用固定 seed 的单变量实验，再逐个叠加结论。</li><li><strong>“工作流能解决所有问题”</strong>：工作流只是把部件连起来的流程，部件的能力仍是上限。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-换采样器和换底模的影响有什么本质区别" tabindex="-1">1. 换采样器和换底模的影响有什么本质区别？ <a class="header-anchor" href="#_1-换采样器和换底模的影响有什么本质区别" aria-label="Permalink to &quot;1. 换采样器和换底模的影响有什么本质区别？&quot;">​</a></h3><details><summary>查看答案</summary><p>底模是能力的来源，决定“会画什么”，换底模等于换地基；采样器只决定去噪过程“怎么走”，是在同一块地基上改变细节与稳定感的表现方式。前者影响内容与上限，后者只影响过程与质感。</p></details><h3 id="_2-出图颜色发灰、对比度异常、细节不自然-应该优先检查哪个部件" tabindex="-1">2. 出图颜色发灰、对比度异常、细节不自然，应该优先检查哪个部件？ <a class="header-anchor" href="#_2-出图颜色发灰、对比度异常、细节不自然-应该优先检查哪个部件" aria-label="Permalink to &quot;2. 出图颜色发灰、对比度异常、细节不自然，应该优先检查哪个部件？&quot;">​</a></h3><details><summary>查看答案</summary><p>优先检查 VAE。VAE 负责潜空间与像素图之间的转换，不匹配或缺失时最典型的症状就是颜色和对比度异常。排除 VAE 之后，再排查模型版本、采样参数等其他因素；如果底模需要搭配独立的 VAE 文件，顺带确认它是否加载正确。</p></details><h3 id="_3-想验证-cfg-是否影响画面-实验应该怎么设计" tabindex="-1">3. 想验证“CFG 是否影响画面”，实验应该怎么设计？ <a class="header-anchor" href="#_3-想验证-cfg-是否影响画面-实验应该怎么设计" aria-label="Permalink to &quot;3. 想验证“CFG 是否影响画面”，实验应该怎么设计？&quot;">​</a></h3><details><summary>查看答案</summary><p>固定同一句提示词、同一个底模、同一个 seed 和其他全部参数，只把 CFG 从一个值改到另一个值，比较两张图。起点相同，差异才能归因给 CFG。如果要同时验证步数，应另做一轮实验，不要一次改两个变量。</p></details><h2 id="下一步阅读" tabindex="-1">下一步阅读 <a class="header-anchor" href="#下一步阅读" aria-label="Permalink to &quot;下一步阅读&quot;">​</a></h2><ul><li>上一篇：<a href="/concepts/base-model">底模是什么</a>：先认识流水线的核心部件，本页把其余部件补齐。</li><li>下一篇：<a href="/concepts/how-it-works">基本原理</a>：解释“为什么分步去噪、文本条件怎么引导画面”。</li><li>相关阅读：<a href="/lora/basics">LoRA 入门</a>：本页只讲了 LoRA 的位置，它的原理与用法后面单独展开。</li><li>相关阅读：<a href="/tools/common-tools">常用工具</a>：这些部件在不同工具里叫什么、放在哪里。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2112.10752" target="_blank" rel="noreferrer">Stable Diffusion 论文</a>：潜空间、文本条件与文生图流水线的原始出处。</li><li><a href="https://arxiv.org/abs/2103.00020" target="_blank" rel="noreferrer">CLIP 论文</a>：图文对照训练的文本编码器，SD 系列文本编码思路的来源。</li><li><a href="https://arxiv.org/abs/2302.05543" target="_blank" rel="noreferrer">ControlNet 论文</a>：给扩散模型加条件控制的原始论文。</li><li><a href="https://github.com/lllyasviel/ControlNet" target="_blank" rel="noreferrer">ControlNet 官方仓库</a>：ControlNet 的官方代码仓库。</li><li><a href="https://arxiv.org/abs/2106.09685" target="_blank" rel="noreferrer">LoRA 论文</a>：小型附加权重方法的原始出处。</li><li><a href="https://huggingface.co/docs/diffusers/index" target="_blank" rel="noreferrer">Hugging Face Diffusers 文档</a>：流水线各部件（编码器、VAE、采样器）的官方实现与说明。</li></ul>`,48)])])}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
